programs.sol:
"""Recognize the ends of parenthesized groups, not just the ')' character.

Short, nonempty groups give a strong positive signal. It fades with the
number of tokens in the group; an unmatched closer is usually negative.
Attached sentence punctuation or a newline weakens the signal, while
mathematical operators strengthen it. Square and curly closers give smaller
positive signals. Empty pairs and closing/reopening transitions are mostly
quiet. State resets at document boundaries.
"""
import math

READS = ()

# Long-group level, short-group boost, and unmatched-closer adjustment.
# These are punctuation classes, not individual vocabulary entries.
RESPONSE = {
    'plain': (-0.63, 3.12, -0.70),
    'comma': (-0.55, 2.47, -0.50),
    'period': (-0.46, 1.94, -0.48),
    'newline': (0.13, 1.07, -0.60),
    'paragraph': (-0.05, 0.97, -0.36),
    'code_punctuation': (0.21, 1.65, -0.26),
    'open_after': (0.52, 1.29, -0.18),
    'power': (1.51, 2.02, -0.33),
    'arithmetic': (1.14, 1.92, -0.63),
    'escape': (0.97, 1.54, -0.58),
    'letter': (1.31, 1.86, -0.26),
}


def punctuation_class(token, after):
    if '\n' in token:
        return 'paragraph' if '\n\n' in token else 'newline'
    if '^' in after:
        return 'power'
    if any(c in after for c in '*/+-') and '(' not in after:
        return 'arithmetic'
    if '\\' in after:
        return 'escape'
    if any(c in after for c in '=:;'):
        return 'code_punctuation'
    if '(' in after:
        return 'open_after'
    if '.' in after:
        return 'period'
    if ',' in after:
        return 'comma'
    if any(c.isalpha() for c in after):
        return 'letter'
    return 'plain'


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, 0, 0, [])
    _, position, character, stack = carry
    token = prefix.token_strings[-1]
    match = None
    closer = None
    # Track parenthesis nesting across tokens, including fullwidth forms.
    for offset, char in enumerate(token):
        if char in '(（':
            stack.append((position, character + offset))
        elif char in ')）':
            if closer is None:
                closer = offset
                match = stack[-1] if stack else None
            if stack:
                stack.pop()

    if closer is not None:
        count = token.count(')') + token.count('）')
        empty = match is not None and character + closer - match[1] == 1
        if empty:
            value = 0.0 if count == 1 else (1.1 if '\n' in token else 1.65)
        else:
            distance = position - match[0] if match else 1000
            short = math.exp(-max(distance - 2, 0) / 10.0)
            before, after = token[:closer], token[closer + 1:]
            level, boost, unmatched = RESPONSE[punctuation_class(token, after)]
            value = level + boost * short
            if match is None:
                value += unmatched
            value += 0.43 * (count - 1)
            if any(c in before for c in "\"'"):
                value += 0.40 - 0.59 * short
            if token[:1].isspace():
                value += 0.34
            if '）' in token:
                value -= 0.25
            if '*' in before:
                value += 0.26
    elif ']' in token or '】' in token:
        after = token.split(']', 1)[-1]
        if '[]' in token:
            value = -0.08
        elif any(c in after for c in '[({'):
            value = 0.05
        elif '】' in token:
            value = 0.30
        elif '\n' in token:
            value = 0.20
        elif '.' in token:
            value = 0.40
        elif ',' in token:
            value = 0.66
        else:
            value = 0.94
    elif '}' in token:
        after = token.split('}', 1)[-1]
        if '{}' in token:
            value = 0.0
        elif '{' in after:
            value = -0.10
        else:
            value = 0.54 if '\n' in token else 0.81
            if ',' in after:
                value = 0.53
            elif '.' in after:
                value = 0.40
            value += 0.15 * max(0, token.count('}') - 1)
    else:
        value = 0.0
    return (document, position + 1, character + len(token), stack), float(value)

programs.haiku:
"""Closing-bracket detector. The component fires on a closing bracket that closes a bracket
opened a few tokens earlier: a ')' closing a short group, like the ')' in "(x)", "f(n)" or
"(1)", is strongest, and the pull fades as the group gets longer. A ')' with no opener
(a list label such as "A)" or "2)") pushes it negative. ']' and '}' give a weaker response.
Tokens that end the bracket with a newline, period or semicolon respond less; tokens that
stack more brackets or operators after it (')^', '))', ')*') respond more."""

import math

READS = ()

PAIRS = {")": "(", "]": "[", "}": "{"}
OPENERS = set("([{")
SHORT_SPAN = 8.6  # tokens: the response falls by a factor e every 8.6 tokens of distance
ENDS = set(" \n\t.;,:")
MORE = set(")]}^*/+-=\\$&|")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        stack = []
    else:
        stack = carry[1]
    pos = prefix.position
    token = prefix.token_strings[-1]
    value = 0.0
    for i, ch in enumerate(token):
        if ch in OPENERS:
            stack.append((ch, pos))
        elif ch in PAIRS:
            if stack and stack[-1][0] == PAIRS[ch]:
                _, start = stack.pop()
                dist = pos - start
                if dist == 0:
                    value = 0.0
                elif ch == ")":
                    rest = token[i + 1:]
                    scale = 1.0
                    if rest and all(c in ENDS for c in rest):
                        scale = 0.6
                    elif any(c in MORE for c in rest):
                        scale = 1.6
                    value = 2.4 * scale * math.exp(-dist / SHORT_SPAN)
                else:
                    value = 0.6
            else:
                value = -1.0 if ch == ")" else 0.0
    return (doc, stack), value

programs.luna:
"""Estimate a larger response when a nonempty parenthetical span closes.

An empty ``()`` pair is nearly quiet, while a closing parenthesis with no
opening one in the visible document context gets a small negative estimate.
Square and curly brackets get weaker positive estimates.
"""

READS = ()

def _parenthesis_size(token):
    if token.startswith(" "):
        return 0.6
    if token.count(")") > 1:
        return 1.45
    after = token[token.rfind(")") + 1:]
    if not after:
        return 1.6
    if after.startswith("\n"):
        return 0.9
    if after.startswith(","):
        return 1.1
    if after.startswith("="):
        return 1.8
    if after.startswith("."):
        return 0.7
    return 1.45

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        openings = []
    else:
        openings = list(carry[1])

    closed = []
    for char in token:
        if char == "(":
            for i in range(len(openings)):
                openings[i] = True
            openings.append(False)
        elif char == ")":
            closed.append(openings.pop() if openings else None)
        elif not char.isspace():
            for i in range(len(openings)):
                openings[i] = True

    next_carry = (document, tuple(openings))
    if ")" in token:
        if True in closed:
            value = _parenthesis_size(token)
        elif closed and all(state is False for state in closed):
            value = 0.0
        elif closed and all(state is None for state in closed):
            value = -0.33
        else:
            value = 0.0
        return next_carry, value
    if "]" in token:
        return next_carry, 0.46
    if "}" in token:
        return next_carry, 0.45
    return next_carry, 0.0

programs.sol:
"""English personal subjects interacting with tense and predicate words.

A recent I, we, or you strengthens this signal: past-tense predicates and
perfect/modal auxiliaries are mostly negative, while think/see/get/find and
several other present verbs and unspaced letter continuations are positive.
The subject fades quickly, except across adverbs and perfect auxiliaries.
Temporal words have a small negative response of their own, stronger after
my/our/your. Document-initial subjects are stronger and have a separate
initial response. This is not a full parser.
"""
READS = ()

IRREGULAR_PAST = set('went came saw took gave got found knew heard met wrote '
    'told bought brought became began ran sat spoke stood lost chose caught '
    'kept sent spent ate drank understood fought woke grew taught chosen '
    'paid built used sold forgot held meant fell'.split())
WEAK_PAST = set('felt won left sent fought woke held read'.split())
PARTICIPLES = set('been done taken seen chosen known given written forgotten '
                 'understood built'.split())
COMMON_PAST = set('said made did wanted designed mentioned knew missed wrote'.split())
PRESENT = set('do use need try take assume regard make go say call start wanna'.split())
ADVERBS = set('just already recently previously first also really always never '
    'still only often usually actually finally honestly originally simply '
    'sometimes certainly probably merely once then even'.split())
NEGATIVE_PAST = set('didn couldn wasn weren hadn'.split())
NOT_PAST = set('proceed exceed indeed speed feed seed need'.split())
SUBJECTS = {'i': 1.0, 'we': .88, 'you': .62, 'he': .20,
            'she': .27, 'they': .27, 'it': .08}
AUXILIARIES = {'had': -3.6, 'was': -3.0, 'were': -2.7,
    'have': -1.25, 'haven': -.9, "'ve": -1.5,
    'are': -1.1, "'re": -1.1,
    'can': -1.2, 'could': -1.75, 'would': -1.0, 'may': -1.0,
    'might': -.8, 'must': -.4, 'will': -.6, 'should': -.65,
    "'ll": -.48, "'d": -.75, 'cannot': -.5,
    'am': -.3, "'m": 0.}


def predicate(word):
    if word in AUXILIARIES:
        return AUXILIARIES[word]
    if word == 'thought':
        return -3.8
    if word in COMMON_PAST:
        return -2.9
    if word in NEGATIVE_PAST:
        return -2.25
    if word in WEAK_PAST:
        return -.95
    if word in PARTICIPLES:
        return -2.1
    if word in IRREGULAR_PAST or (
        len(word) > 3 and word.endswith('ed') and word not in NOT_PAST
    ):
        return -2.0
    if word == 'set':
        return -.85
    if word in {'know', 'mean'}:
        return -1.0
    if word in {'understand', 'going'}:
        return -.6
    if word == 'want':
        return -.3
    if word in {'just', 'already', 'recently', 'originally'}:
        return -1.35
    if word in ADVERBS:
        return -.5
    if word in {'get', 'find'}:
        return 1.35
    if word in {'think', 'see'}:
        return .95
    if word == 'need':
        return .15
    if word in PRESENT:
        return .6
    if word == 'don':
        return .25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    at_start = carry is None or carry[0] != doc
    if at_start:
        carry = (doc, '', 0.0, '', '')
    _, pronoun, strength, previous, previous_raw = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().strip('"“”‘(（>').lower().replace('’', "'")
    if word.startswith("'") and word[1:] in SUBJECTS:
        word = word[1:]
    response = predicate(word)
    if word in {'are', "'re"} and pronoun == 'you':
        response = -1.4
    if response > 0 and pronoun == 'we':
        response *= 1.2
    if not raw[:1].isspace() and response == 0 and word.isalpha():
        response = .45
    if word == "'t":
        response = (-2.7 if previous == 'didn' else
                    -1.4 if previous in NEGATIVE_PAST
                    else 1.0)
    if word == 'not' and previous in {'did', 'could', 'was', 'were'}:
        response = -1.8
    if word == 'had' and previous in {'have', "'ve"}:
        response = -1.5
    value = -.001 + strength * response
    if word in {'previous', 'earlier', 'previously'}:
        value -= 1.4 if previous in {'my', 'our', 'your'} else .65
    boundary = (raw[:1].isspace() or not previous_raw[-1:].isalpha()
                or raw.lstrip()[:1] in "\"'“(（>" or word == 'i' and 'I' in raw)
    if word in SUBJECTS and boundary:
        pronoun, strength = word, SUBJECTS[word]
        if at_start:
            strength *= 1.45
            value = -.35 if word == 'i' else .65 if word == 'we' else .2
        if word == 'i' and 'I' not in raw:
            strength *= .7
    elif word in NEGATIVE_PAST or word == 'don':
        strength *= .8
    elif word in ADVERBS:
        strength *= .8
    elif word == 'did':
        strength *= .8
    elif word in {'have', 'had', 'haven', "'ve"}:
        strength *= .6
    elif word == 'can':
        strength *= .5
    elif word == "'t" and response < 0:
        strength *= .4
    else:
        strength *= .12
    return (doc, pronoun, strength, word, raw), float(value)

programs.luna:
"""Guess the small first-person predicate feature this component often responds to.

It gives a signed nudge after a personal subject: negative for common helper or
past-tense predicates, positive for a few present-tense report/action verbs.
It stays silent elsewhere; this is a coarse linguistic sketch, not a word model.
"""

READS = ()

SUBJECTS = {"i", "we", "you", "he", "she", "they", "it"}
HELPERS = {
    "am", "are", "is", "was", "were", "be", "been", "being",
    "have", "has", "had", "do", "does", "did", "can", "could",
    "will", "would", "should", "must", "might",
}
REPORT_OR_ACTION = {
    "think", "know", "see", "say", "believe", "assume", "regard",
    "use", "get", "feel", "mean", "find", "remember",
}


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0

    subject = prefix.token_strings[t - 1].strip().lower()
    word = prefix.token_strings[t].strip().lower()
    if subject not in SUBJECTS:
        return None, 0.0

    if word in REPORT_OR_ACTION:
        return None, 0.55
    if word in HELPERS or word.endswith(("ed", "en", "ing")):
        return None, -0.55
    return None, 0.0

programs.sol:
"""Local responses to 'on', 'about', and quotation openings.

These boundaries are positive, except that familiar dependence/topic phrases
weaken them. Quotes are strongest after prose words, not code punctuation.
Reply-subject colons are negative. Other tokens are approximately zero.
The short text tail is reset whenever a new document begins.
"""
import re
import unicodedata

READS = ()
DEPENDENCE = set('''based depend depends depended depending dependent dependence
    dependency independent rely relies relied relying reliance'''.split())
TOPIC_HEADS = set('''focus focuses focused focusing work works worked working
    information info data evidence facts question questions details detail
    advice guidance instructions restrictions constraints limitations research
    essay thesis book books literature discussion study studies report reports
    lecture lectures paper papers topic topics guide tutorial lesson lessons
    hypothesis hypotheses test tests piece pieces review reviews'''.split())
TOPIC_VERBS = set('''talk talks talked talking ask asks asked asking inquire
    inquires inquired inquiring learn learns learned learning speak speaks spoke
    speaking write writes wrote writing written read reads reading study studies
    studied studying debate debates debating preach preaches preaching'''.split())
THOUGHT = set('think thinks thought thinking know knows knew knowing'.split())
ARTICLES = {'a', 'an', 'the', 'any', 'some'}
FUNCTION_WORDS = set('''of as to for or from in by on that with without into
    under among between like'''.split())
CODE_WORDS = set('''return case echo print printf command else import include
    open processing'''.split())


def activation(token, tail):
    m = re.search(r'(\w+)\s*$', tail)
    word = m.group(1).lower() if m else ''
    text = token.strip()
    if text.lower() in {'on', 'about'}:
        if text == 'On':
            return 1.40
        if text.lower() == 'on' and not token[0].isspace():
            return 0.12 if tail[-1:].isalpha() else 0.80
        if text == 'ON':
            return 0.71
        if word in {'article', 'articles'}:
            return -1.10 if text.lower() == 'on' else -1.70
        if text.lower() == 'on':
            if word in DEPENDENCE:
                return 0.04
            return 0.13 if word in TOPIC_HEADS else 1.10
        if word in TOPIC_HEADS or word in TOPIC_VERBS:
            return 0.08
        if word in THOUGHT:
            return 0.48
        if word == 'more':
            return -0.13
        return -0.47 if word == 'story' else 1.06
    if token in (' "', " '", ' “', ' ‘', '“', '‘'):
        # Triples: straight double quote, apostrophe, curly opening quote.
        style = 2 if text in ('“', '‘') else 1 if text == "'" else 0
        if token == '“' and tail and 'LATIN' in unicodedata.name(tail[-1], ''):
            return 0.33  # Often a closing quote in German-language text.
        if not tail or '\n' in tail[-3:]:
            return (0.07, 0.05, 0.42)[style]
        if len(tail) - len(tail.rstrip()) >= 2:
            return (-0.10, -0.10, 0.42)[style]
        if word in ARTICLES:
            return (1.27, 1.03, 1.32)[style]
        if word in FUNCTION_WORDS:
            return (1.09, 0.76, 1.13)[style]
        if word in CODE_WORDS:
            return (0.23, 0.05, 1.13)[style]
        if word:
            return (0.91, 0.64, 1.13)[style]
        end = tail.rstrip()
        if end.endswith(('.', '!', '?', '."', ".'")):
            return (0.57, 0.44, 0.80)[style]
        if end.endswith(',') and len(end) > 1 and end[-2].isalnum():
            return (0.50, 0.18, 0.85)[style]
        if end.endswith(':') and not end.endswith(('":', "':")):
            return (0.30, 0.08, 0.65)[style]
        return (0.0, 0.05, 0.71)[style]
    if token == ':' and word in {'re', 'article', 'articles'}:
        return -1.08 if word == 're' else -1.40
    if re.fullmatch(r'[._/(\-]([Oo]n|ON)', token):
        return 1.14
    if re.match(r'[. ]on[A-Z]', token):
        return 0.75  # Event-handler names, e.g. onClick.
    if text == 'onto':
        return 0.54
    if token == '="':
        return 0.75 if word in {'class', 'classname'} else 0.38
    if token in ('{"', ' {"'):
        return -0.30 if token == '{"' else -0.14
    if text in ('["', "['", '("', "('") or token == '\\"':
        return -0.10
    if token in (' на', ' auf'):
        return 0.55 if token == ' на' else 0.20
    if token in ('「', ' «', ' „'):
        return 0.72 if token != ' „' else 0.59
    if len(token) > 1 and token[-1] in '“「' and token[-2] in '：（，、。':
        return 0.65
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, (tail + token)[-80:]), activation(token, tail)

programs.luna:
"""A small lexical detector for a layer-zero MLP response.

The harvested strong responses cluster around the preposition “on” and
opening quotation marks. The program gives those token classes positive
scores, with a smaller score for a couple of related punctuation/text cues.
"""

READS = ()

ON = {" on", " On", "On", "ON"}
OPEN_QUOTES = {' "', '"', ' “', ' ‘', "'"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in ON:
        return None, 1.08
    if token in OPEN_QUOTES:
        return None, 0.75
    if token == '="':
        return None, 0.55
    if token in {" about", " concerning"}:
        return None, 0.75
    return None, 0.0

programs.sol:
"""Approximate a six detector and a secondary legal-vocabulary detector.

Recognize 6, 六, English six-words and June. Digit responses depend on number
boundaries, repetition and document position. Legal participants, testimony
and evidence also respond; a remembered legal context strengthens ambiguous
words. Other small number words are slightly negative. Most tokens are near
zero; smaller word-specific effects are omitted.
"""
import re
import unicodedata

READS = ()
ROLES = {
    'plaintiff', 'plaintiffs', 'defendant', 'defendants', 'appellant',
    'appellants', 'respondent', 'respondents', 'petitioner', 'petitioners',
    'counsel',
}
LEGAL = ROLES | {
    'court', 'contract', 'agreement', 'lease', 'statute', 'jurisdiction',
    'litigation', 'affidavit', 'pursuant', 'foregoing', 'testified',
}
SIX_WORDS = {'six', 'sixth', 'sixteen', 'sixteenth', 'sixty', 'sixtieth'}
EVIDENCE = {'court', 'courts', 'evidence', 'witness', 'witnesses'}
ALLEGATIONS = {'allege', 'alleges', 'alleged', 'alleging', 'allegedly'}
OTHER_NUMBERS = {'three', 'four', 'five', 'seven', 'eight', 'nine'}


def word_response(word, token, legal):
    lower = word.lower()
    fragment = token.isalpha() and token.lower() != lower
    if not word or word.isupper():
        return -0.001
    if lower in SIX_WORDS:
        if lower in {'sixth', 'sixtieth'}:
            return 0.16 if fragment else 0.46
        if lower.startswith('sixteen'):
            return 0.18 if fragment else 0.24
        if lower == 'sixty':
            return 0.27 if fragment else 0.41
        return 0.36 if token[0].isspace() else 0.29
    if lower == 'june' and not fragment:
        return (0.28 if token[0].isspace() else 0.24) + 0.10 * legal
    if lower in ROLES:
        if lower == 'defendants':
            return 0.64
        if lower == 'respondents':
            return 0.18
        if fragment:
            return 0.75 if lower.startswith('petition') else 0.40
        return 0.50 if word[0].isupper() else 0.43
    if word in {'Plaint', 'Respond'}:
        return 0.30
    if lower in ALLEGATIONS or lower in {'testify', 'testifies'}:
        return 0.28
    if lower == 'testified':
        return 0.48 + 0.19 * legal
    if lower == 'foregoing':
        return 0.43
    if lower == 'parties' and not fragment:
        return 0.26 + 0.32 * legal
    if lower == 'veteran' and not fragment:
        return 0.40 if word[0].isupper() else 0.30
    if lower == 'facts':
        return 0.15 + 0.20 * legal
    if lower in EVIDENCE:
        return 0.08 + 0.08 * legal
    if lower == 'company':
        return 0.08 + 0.08 * word[0].isupper() + 0.10 * legal
    return -0.08 if lower in OTHER_NUMBERS else -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position, previous, word, legal = (0, '', '', False)
    if carry is not None and carry[0] == doc:
        _, position, previous, word, legal = carry
    token = prefix.token_strings[-1]
    match = re.search(r'[A-Za-z]+$', token)
    # Retain only the unfinished word, so split legal names can be recognized.
    if match:
        piece = match.group()
        word = word + piece if match.start() == 0 else piece
    else:
        word = ''
    value = word_response(word, token, legal)
    if len(token) == 1 and token.isdecimal():
        digit = unicodedata.decimal(token)
        value = 0.0 if digit < 2 else (-0.005 if digit < 4 else -0.015)
        if digit == 6:
            value = 0.408 + 0.136 / (position + 1) ** 0.5
            if previous == '6':
                value -= 0.054
            elif previous.isspace():
                value -= 0.037
            elif len(previous) == 1 and previous.isdecimal():
                value += 0.024
    elif token == '六':
        value = 0.49
    legal = legal or word.lower() in LEGAL
    next_carry = (doc, position + 1, token, word[-32:], legal)
    return next_carry, float(value)

programs.luna:
"""Mark written sixes and the legal-case vocabulary this component often favors."""

import unicodedata

READS = ()

SIX_WORDS = {"six", "sixth", "sixty"}
LEGAL_CUES = {
    "appellant", "appellants", "plaintiff", "plaintiffs",
    "defendant", "defendants", "respondent", "respondents",
    "petitioner", "petitioners", "counsel", "taxpayer", "taxpayers",
    "parties", "entitled", "foregoing", "pretext", "pursuant",
    "被告", "认可", "证据", "机关",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold()
    is_six_digit = len(token) == 1 and unicodedata.decimal(token, None) == 6
    if is_six_digit:
        return None, 0.43
    if token == "june":
        return None, 0.30
    if token in SIX_WORDS:
