# Groups of inflections, word pieces, and round-related vocabulary.
FAMILIES = (
    # English inflections and token-sized word pieces.
    (-4.0, {'rounds'}),
    (-3.2, {'rounded'}),
    (-3.3, {'rounding'}),
    (-1.1, {'ound'}),
    (-0.9, {'ounds', 'ounded', 'ounding'}),
    (-0.4, {'rou'}),
    (-0.9, {'surround', 'surrounds', 'surrounding'}),
    (-0.35, {'surrounded', 'surroundings'}),
    (-0.6, {'spherical'}),
    # Numeric formatting and currency vocabulary.
    (-1.2, {'format'}),
    (-0.8, {'formats', 'formato'}),
    (-0.4, {'formatted', 'formatting', 'formatter', 'decimal', 'decimals'}),
    (-0.8, {'sprintf', 'currency'}),
    (-0.5, {'pound', 'pounds'}),
    # Chinese/Japanese round characters; around in several languages.
    (-2.4, {'圆', '圓'}),
    (-1.45, {'円', '围绕', 'вокруг'}),
    (-1.05, {'круг', 'округ', 'rund', 'rond', 'autour', 'حول'}),
    (-0.75, {'绕', '繞', 'около'}),
    (-0.4, {'围', '圍', '周围'}),
    (-0.6, {'格式'}),
    (-1.1, {'workaround', 'turnaround', 'adians'}),
    (-0.9, {'丸', '周り', 'tofixed'}),
)
WEIGHTS = {word: value for value, group in FAMILIES for word in group}
TOPIC_VERBS = {
    'talk', 'talks', 'talking', 'talked', 'think', 'thinks', 'thinking',
    'thought', 'worry', 'worries', 'worried', 'worrying', 'know', 'concerned',
}
TOPIC_NOUNS = {'information', 'details', 'knowledge', 'concerns'}
WALK_VERBS = {'walk', 'walks', 'walking', 'walked', 'go', 'goes', 'going'}
ORBIT_VERBS = {'revolve', 'revolves', 'revolving', 'orbit', 'orbits', 'orbiting'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', False)
    _, previous, contiguous = carry
    token = prefix.token_strings[-1]
    word = token.strip().strip('._-/=()"\'').lower()
    value = WEIGHTS.get(word, 0.0)
    if word == 'round':
        if token.isalpha() and contiguous and previous.endswith(('sur', 'g')):
            value = -1.4
        elif token.startswith('_'):
            value = -4.1
        elif token[:1].isspace():
            value = -5.7 if token.strip() == 'Round' else -5.2
        elif token.startswith(('.', '(')):
            value = -5.3
        else:
            value = -4.7
    elif word == 'rounded' and not token[:1].isspace():
        value = -0.8 if contiguous and previous.endswith('sur') else -2.4
    elif word == 'around':
        value = -3.2
        if previous in ORBIT_VERBS or previous in {'centered', 'centred'}:
            value = -1.8
        elif previous in WALK_VERBS:
            value = -4.0
        elif previous in {'look', 'looks', 'looking', 'looked', 'turn', 'turns'}:
            value = -2.65
        elif token.startswith('-'):
            value = -2.4
    elif word in {'about', 'abouts'}:
        value = -0.27 if previous in TOPIC_VERBS else -0.7
        if previous in TOPIC_NOUNS:
            value = -0.35
    elif word in {'circular', 'ircular'}:
        value = -2.0 if token.strip().startswith('C') else -1.6
    elif word == 'of' and previous in {'round', 'rounds'}:
        value = -1.5
    elif word in {'ound', 'ounds', 'ounded', 'ounding'} and previous == 'r':
        value = -3.4
    elif word == 'fmt':
        value = -0.5 if token[:1].isspace() else -0.25

    match = re.search(r'[A-Za-z]+$', token)
    last = match[0].lower() if match else ''
    if token.isascii() and token.isalpha() and contiguous:
        last = (previous + last)[-30:]
    elif token.isspace():
        last = previous
    return (doc, last, bool(match)), value

