    now = prefix.token_strings[-1]
    if _is_caps(now):
        return carry, (0.8 if len(_letters(now)) == 1 else 1.3)
    if now == "_" and len(prefix.token_strings) > 1 and _is_caps(prefix.token_strings[-2]):
        return carry, 0.7
    return carry, 0.0

