"""Detect mixed tab-and-space indentation within a whitespace token.

The large positive response is to tabs followed by spaces, often after code
line numbers. It peaks at short indents and fades at deep ones. A token that
also ends the line gets a weaker response. Pure tabs are slightly negative.
The calibration is by whitespace width, not by token ID or surrounding code.
Single Chinese characters from a positive/aspirational naming vocabulary get
an additional, modest negative response. This does not detect whole names.
"""
READS = ()

# Positive and aspirational elements common in Chinese given names and brands.
NAME_ELEMENTS = frozenset(
    "安康博宇创創联聯恒讯訊瑞利泰达達捷信盛丰豐智兴興宏伟偉杰傑"
    "华華嘉荣榮福祥德宝寶诚誠永乐樂豪益俊明慧胜勝艺藝鸿鴻"
)


def token_value(text):
    if text.strip() in NAME_ELEMENTS:
        return -0.22
    if not text or not text.isspace():
        return 0.0
    tabs = text.count('\t')
    spaces = text.count(' ')
    if not tabs:
        return 0.0
    if not spaces:
        return -0.025 * min(tabs, 8)
    if not text.startswith('\t'):
        return 0.0
    if '\n' in text or '\r' in text:
        return max(0.3, 0.54 - 0.025 * spaces)
    if spaces <= 3:
        value = 1.055
    elif spaces == 4:
        value = 0.946
    else:
        value = max(0.66, 1.234 - 0.042 * (spaces - 5))
        if spaces % 2 == 0:
            value = max(0.66, value - 0.23)
    value += 0.15 * min(tabs - 1, 2)
    if text.endswith('\t'):
        value *= 0.5
    return value


def step(carry, prefix, upstream):
    return None, float(token_value(prefix.token_strings[-1]))

