"""Recognize country words, with smaller signals for country attributes.

The strongest negative signal is the English noun 'country', including
case and spacing variants; its plural is weaker. Administrative places,
languages, currency, weather, and holidays have smaller negative signals. 'Of'
immediately after one of these words keeps part of its signal (as in
'country of origin'). All other tokens predict zero.
"""

READS = ()


def lexical_signal(token):
    word = token.strip()
    lower = word.lower()
    if lower in {'country', '-country', 'ountry'}:
        value = -7.44
        if lower == 'ountry':
            return -6.8
        if token == word:
            value -= 0.85
        if word[0].isupper():
            value -= 1.1
        return value
    if lower in {'countries', 'ountries'}:
        value = -4.82 - (0.8 if token == word else 0.0)
        return value - (0.8 if token != word and word[0].isupper() else 0.0)
    if lower == 'countryside':
        return -2.2
    if lower in {'nation', 'nations', 'national'}:
        return -1.4 if word == 'nation' else -1.05
    if lower in {'county', 'counties'}:
        return -1.17
    if lower in {'city', 'cities'}:
        return -1.35 if word == 'city' else -1.03
    if lower in {'province', 'airport'}:
        return -0.7
    if lower in {'town', 'towns', 'district', 'region', 'regions'}:
        return -0.3
    if lower in {'language', 'languages', '-language', 'anguage'}:
        return -1.3 - (0.45 if token == word or word[0].isupper() else 0.0)
    if lower in {'lang', '.lang', '/language'}:
        return -0.4 if token == 'lang' else -0.9
    if lower in {'currency', 'currencies', '.currency'}:
        return -1.5
    if lower in {'weather', '/weather'}:
        return -1.8 if word[0].isupper() else -2.2
    if lower in {'holiday', 'holidays', 'continent'}:
        return -1.1
    # Country nouns and stems in Spanish, German, Russian, Thai and Korean.
    if lower in {'país', 'países', 'länder', 'стран', 'страны', 'ประเทศ', '나라'}:
        return -3.4 if lower == 'país' else -2.2
    # Chinese (simplified/traditional) and Korean country/place vocabulary.
    if word in {'国', '國'}:
        return -2.7 if word == '国' else -2.05
    if word in {'国家', '國家', '城市', '국', '국가'}:
        return -1.3 if word in {'國家', '국', '국가'} else -1.65
    if word in {'中国', '中國', '国内', '全国', '我国', '外国'}:
        return -1.0
    if word in {'语言', '語言', '语', '語'}:
        return -0.8
    if word == '天气':
        return -2.0
    if word in {'货币', '貨幣'}:
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    base = lexical_signal(token)
    value = base
    if carry is not None and carry[0] == doc and token == ' of':
        previous = carry[1]
        value = previous * (0.515 if previous < -4.0 else 0.8)
    return (doc, base), value

