COUNTRY = {"country", "-country", "ountry"}
# Plural and foreign-language words for countries.
COUNTRIES = {"countries", "countryside", "país", "países", "Länder", "страны", "стран", "państw"}
# Words for nations, peoples, places and languages.
PLACES = {
    "nation", "nations", "national", "county", "counties", "city", "cities",
    "language", "languages", "currency", "currencies", "continent", "coun",
}
# Chinese characters for country, nation, city and language.
CHINESE = {"国", "國", "国家", "國家", "中国", "国内", "外国", "我国", "城市", "语言"}
# Words after which " of" is weakly negative.
PLACE_OF = {"city", "language", "province", "town", "district", "republic", "regions"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    lower = word.lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word == "of":
        if before in COUNTRY:
            return None, -3.8
        if before in PLACE_OF:
            return None, -0.7
        return None, 0.0
    if lower in COUNTRY:
        return None, -7.5
    if word in COUNTRIES or lower in COUNTRIES:
        return None, -3.9
    if lower in PLACES:
        return None, -1.2
    if word in CHINESE:
        return None, -1.7
    return None, 0.0

