"""Line endings, especially indented empty lines and standalone code braces.

Newline tokens usually give positive responses. Trailing spaces and tabs make
them stronger, especially on an empty line. Paragraph breaks and line-ending punctuation change
its size. Most other tokens predict near zero. The state stores the latest 1000
characters of the current line and resets at document boundaries.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    s = raw.replace('\r\n', '\n')
    parts = s.split('\n')
    line = tail + parts[0]
    carry = (doc, (tail + s).rsplit('\n', 1)[-1][-1000:])
    n = len(parts) - 1
    if not n:
        if '\r' in s or '\f' in s:
            return (doc, ''), 0.7
        return carry, -0.006
    content = s.strip()
    indented = line.startswith((' ', '\t'))
    if not content:
        padding = line[len(line.rstrip(' \t')):]
        width = len(padding.expandtabs(4))
        empty = not line.strip()
        tabs = parts[0].count('\t')
        value = 0.24 if n == 1 else min(1.3, 0.57 + 0.35 * (n - 2))
        value += 0.17 * indented
        if tabs:
            value = 2.12 + 0.55 * min(tabs - 1, 3) + 1.2 * empty
        elif width:
            value = min(3.8, 0.42 * width + 0.03)
            if empty:
                value = min(4.0, 1.6 + 0.85 * math.log2(width))
            if n > 1 and width <= 2:
                value = 1.15 if empty else 0.44 * width
            if '\r' in raw and width == 1:
                value = 0.03
        inner_width = max((len(p.expandtabs(4)) for p in parts[1:-1]), default=0)
        if inner_width:
            value = max(value, 1.0 + 0.4 * math.log2(inner_width))
    elif content in ('{', '}'):
        if line.strip() == content and indented:
            value = (1.2 if content == '{' else 1.03) + 0.35 * (n > 1)
        else:
            value = (0.0 if content == '{' else 0.4) + 0.45 * (n > 1)
    else:
        end = content[-1]
        value = 0.52 if n > 1 else 0.01
        if end in '.!。':
            value = 0.29 if n > 1 else 0.03
        elif end in '?？':
            value = 0.05 if n > 1 else -0.11
        elif end in ',:':
            value = 0.03 if n > 1 else 0.24 * (end == ',')
        elif end == ';':
            value = 0.73 if n > 1 else 0.03
        elif s.startswith(' ') and end in '}]),':
            value = 0.5
    return carry, float(value)

