    'pay': 3.7, 'gay': 3.3, 'jay': 3.6, 'hay': 4.0,
    'may': 2.5, 'say': 2.4, 'day': 1.7, 'way': 1.6,
    'play': 1.35, 'stay': 2.15, 'pray': 2.5, 'clay': 3.7,
    'gray': 2.7, 'grey': 2.3, 'spray': 2.2,
    'delay': 2.1, 'relay': 2.7, 'convey': 2.2,
    'essay': 1.75, 'assay': 1.85, 'today': 1.25,
}
