    'y': .5, 'py': .6, 'ya': .6, 'ye': .65, 'ie': .3, 'ies': .4,
    'ای': 1.8, 'ی': .5, 'ي': .55, '이': 1.2,
    'イ': 1.8, 'レイ': 4.9, 'ライ': 1.8, 'マイ': 4.3,
    'い': .6, 'ย': 2.5, 'อย': 2.5,
