"""Approximate layout-boundary responses, not the full lexical activation.

A space bundled with a line break receives a position- and repetition-based
response, usually negative for early, unfamiliar breaks. Previous punctuation,
numbers and uppercase text adjust it. Opening curly single quotes, page breaks
and five/six-hash markers also receive negative responses. All state resets at
document boundaries; unrecognized tokens receive zero.
"""

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        position, counts, previous = 0, {}, ""
    else:
        _, position, counts, previous = carry
    count = counts.get(token, 0)
    decay = 1.0 / (1.0 + position / 16.0)
    value = 0.0
    if token == " \n":
        repetition = 1.0 / (1.0 + count) ** 0.5
        value = (0.15 + 1.08 * decay - 0.27 * repetition
                 - 1.77 * decay * repetition)
        if previous.rstrip().endswith((".", "?", "!", ":", ";")):
            value -= 0.07
        elif previous.rstrip().isdigit():
            value -= 0.12
        elif previous.strip().isupper():
            value -= 0.09
    elif token == " \n\n":
        repetition = 1.0 / (1.0 + count) ** 0.5
        value = (0.06 + 0.54 * decay - 0.16 * repetition
                 - 1.28 * decay * repetition)
        if previous.rstrip().endswith((".", "?", "!", ":", ";")):
            value += 0.045
    elif token == " \r\n":
        value = -0.89 / (1.0 + position / 12.0)
    elif token in ("‘", " ‘"):
        value = -0.31 if token.startswith(" ") else -0.39
    elif token == "\f":
        value = -0.68
    elif token.strip() in ("#####", "######"):
        value = -0.40
        if "..." in previous:
            value = -3.3
        elif previous.strip() and set(previous.strip()) == {"#"}:
            value = 0.0
    if position == 0 and token in (" \n", " \r\n"):
        value = -1.05
    if token == " \n" and previous.strip() in ("APPLICATION", "APPLICATIONS"):
        value -= 0.9
    if token in (" \n", " \n\n"):
        counts[token] = count + 1
    return (document, position + 1, counts, token), float(value)

