OPENING_SINGLE_QUOTE = {"‘", " ‘"}
PAGE_BREAK = {"\x0c"}
SPACE_LINE_BREAK = {" \n": -0.12, " \r\n": -0.06, " \n\n": -0.01}
IDENTIFIER_SYMBOLS = {"_", "__", "`", " `", "\\n", "~", "->"}
CODE_PUNCTUATION = {"(", ";\n", "();\n", " +", " |", '",', "/*", "<", "@"}


def step(carry, prefix, upstream):
    """The activation at the newest token of the prefix; no state is carried."""
    token = prefix.token_strings[-1]
    if token in OPENING_SINGLE_QUOTE:
        value = -0.3
    elif token in PAGE_BREAK:
        value = -0.7
    elif token in SPACE_LINE_BREAK:
        value = SPACE_LINE_BREAK[token]
    elif token in IDENTIFIER_SYMBOLS:
        value = 0.03
    elif token in CODE_PUNCTUATION:
        value = -0.03
    else:
        value = 0.0
    return carry, float(value)

