THIS_WORDS = {
    'ce': 0.75, 'cet': 0.85, 'cette': 1.45, 'ces': 0.5,
    'este': 1.1, 'esta': 0.95, 'questo': 1.5, 'questa': 1.25,
    'dieser': 1.5, 'dieses': 1.5, 'diesem': 1.5,
    'diese': 1.2, 'diesen': 1.0,
    'этот': 0.85, 'этого': 0.8, 'эту': 0.85,
    'этом': 1.15, 'этой': 1.15, 'это': 0.35,
    'bu': 0.5, 'ini': 0.7, 'này': 0.7,
}
# These spellings do not use spaces to mark the start of each word.
CJK_DEMONSTRATIVES = {
    '这': 1.0, '這': 1.0, '这个': 0.6, '這個': 0.6,
    '此': 2.1, 'この': 2.5, 'これ': 1.6,
}
PREPOSITIONS = frozenset(
    'in at to for on from by with through upon under'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
        position += 1
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip('(>.,\"“')
    word = spelling.lower()
    capital = spelling.istitle()
    value = 0.0
    if word == 'this':
        value = 3.53 + 0.23 * capital + 0.38 * (token == 'This')
        value += (0.83 + 0.40 * capital) / sqrt(1 + position / 30)
        if position == 0 and capital:
            value = 6.83 if token == 'This' else 5.59
        elif previous == 'like':
            value -= 1.5
        elif previous == 'do':
            value -= 0.85
        elif previous == 'in':
            value -= 0.27
        if token.strip().startswith('('):
            value -= 1.0
    elif word == 'these':
        value = 0.9 + 0.2 * capital
    elif word == 'here':
        value = 0.73 + 0.12 * capital
    elif word == 'which':
        if previous.endswith(','):
            value = 0.65
        elif previous in PREPOSITIONS:
            value = -0.2 if previous in {'in', 'at'} else 0.05
        else:
            value = 0.52
    elif word == 'following':
        value = 0.5
    elif word == 'that':
        value = 0.4 if capital else 0.08
    elif word == '이':
        value = 1.2 if token.startswith(' ') else 0.4
    elif word in CJK_DEMONSTRATIVES:
        value = CJK_DEMONSTRATIVES[word]
    elif token[:1].isspace() or capital:
        # Bare lower-case fragments such as 'ce' also occur inside words.
        value = THIS_WORDS.get(word, 0.0)
    return (doc, position, token.strip().lower()), float(value)

