        value = -3.1
    elif "春" in token:
        value = -5.0 if token.strip() == "春" else -3.5
    elif "秋" in token:
        value = -4.2 if token.strip() == "秋" else -3.2
    elif "autumn" in word:
        value = -2.5
    elif "spring" in word:
        value = -1.5
    elif word in TIME_OF_DAY:
        value = -0.75
    elif word in FALL_WORDS:
        value = -0.5
    elif word in WEAK_WORDS or "冬" in token or "夏" in token:
        value = -0.3
    elif "season" in word:
        value = -0.2
    else:
        value = 0.0
    return carry, float(value)

