def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    lower = token.lower()
    doc = prefix.document_ids[-1]
    follows_spr = carry == ("spr", doc)

    # Common English names, plus related words in this same lexical family.
    if "morning" in lower:
        value = -0.85
    elif "afternoon" in lower:
        value = -0.95
    elif "evening" in lower:
        value = -0.55
    elif "spring" in lower:
        value = -2.5
    elif "autumn" in lower or "winter" in lower or "summer" in lower:
        value = -1.0
    elif "fall" in lower:
        value = -0.6
    elif "season" in lower:
        value = -0.55
    elif "brunch" in lower:
        value = -0.7
    elif "spr" in lower and lower.strip().endswith("spr"):
        value = -1.5
    elif lower.strip() == "ing" and follows_spr:
        value = -2.0
    else:
        value = 0.0

    # These characters mean spring, summer, autumn, or winter in Chinese
    # and Japanese; decode the joined prefix when a byte token is incomplete.
    if value == 0.0 and any(ch in token for ch in "春夏秋冬"):
        value = -2.5
    if value == 0.0 and "\ufffd" in token:
        recent = prefix.text_prefixes[-1]
        if recent and recent[-1] in "春夏秋冬":
