    return next_carry, float(value)

programs.sol:
"""Approximate an opening-structure response from token text and local syntax.

Square/curly openings, code blocks, TeX arguments, JSON and markup have
training-derived response strengths. Nested Wolfram box/list expressions
have larger responses. Empty brackets are weakly negative; document and
turn boundaries have separate values. Ordinary text defaults to zero.
The state is the last 120 characters, reset when the document changes.
"""
import re

READS = ()
HTML_TAGS = set('''div span p a b i em strong code pre ul ol li table tr td
    th head body title script style br img input form button section
    article nav header footer h1 h2 h3 h4 h5 h6'''.split())
BOUNDARIES = {
    '<|endoftext|>': 1.10,
    '<|im_end|>': -0.094,
    '<tool_response>': 0.149,
    '</tool_response>': 0.072,
    '</tool_call>': -0.219,
}


def response(token, before):
    s = token.lstrip()
    space = s != token
    if token in BOUNDARIES:
        return BOUNDARIES[token]
    if s in ('http', 'https'):
        return 0.53
    if '《' in s:
        return 1.0
    if '【' in s:
        return 0.50

    # Use the last still-open curly delimiter, including syntax in this token.
    if '{' in s and s.rfind('{') > s.rfind('}'):
        i = token.rfind('{')
        left = (before + token[:i]).rstrip()
        body = token[i + 1:]
        if left.endswith(('_', '^')):
            return 0.62 if token.startswith('}') else 0.90
        if left.endswith(('$', '#')):
            return 0.94
        if '[' in s and s.rfind('[') > s.rfind(']'):
            return 1.70
        if s.startswith('}{'):
            return 0.17
        if s == '{"' and not space:
            return -0.144
        command = re.search(r'\\([A-Za-z]+)$', left)
        if command:
            name = command.group(1)
            if name in ('text', 'textrm', 'textbf', 'textit', 'cite'):
                return 0.0
            if name == 'begin':
                return 1.45
            if name == 'end':
                return 0.79
            if name in ('frac', 'dfrac', 'tfrac', 'mathrm', 'mathbf'):
                return 0.43
            if name in ('label', 'ref', 'eqref'):
                return 0.29
            return 0.68
        if '":{' in s:
            return 1.63
        if '\\' in body:
            return 1.16 if space else 0.93
        if left.endswith((')', '=>', 'else', 'try', 'finally', 'do')):
            return 0.85 if before.endswith(('\n', '\r')) else 1.07
        if left.endswith(('=', 'return', 'struct', 'enum', 'import')):
            return 0.28
        if left.endswith('('):
            return 0.48
        if '\r\n' in body:
            return 1.02
        if '\n' in body:
            return 0.73 if space else 0.58
        if body.startswith('"'):
            return 0.82
        if body.startswith("'"):
            return 0.32
        return 0.64

    if '[' in s and s.rfind('[') > s.rfind(']'):
        i = token.rfind('[')
        left = (before + token[:i]).rstrip()
        body = token[i + 1:]
        # Wolfram display expressions nest box and list arguments.
        if re.search(r'(?:Row|Fraction|Superscript|Subscript)Box$', left):
            return 1.20 if body.startswith('"') else 2.90
        if before.endswith('[List') and 'Box' in before:
            return 1.97 if body.startswith('"') else 4.05
        if body[:1] in ('"', "'"):
            return 0.63
        if left.endswith('":'):
            return 1.48
        if body[:1].isalpha():
            return 1.04
        if left.endswith('='):
            return 0.64
        if not s.startswith('['):
            return 0.62
        if before.endswith(('\n', '\r')):
            return 0.59
        return 0.81 if space else 0.96
    if '[]' in s or '{}' in s:
        return -0.11

    if s.startswith('<<'):
        return -0.21
    if s.endswith('<'):
        if '><' in s:
            return 1.10
        if not before.split('\n')[-1].strip():
            return 0.76
        return 0.23
    if re.fullmatch(r'<[A-Za-z]+', s):
        return 0.54 if s[1:].lower() in HTML_TAGS else 0.61
    if s in HTML_TAGS and re.search(r'</?$', before):
        if s in ('div', 'section', 'tr'):
            return 1.13 if before.endswith('</') else 1.60
        if s in ('span', 'em', 'i', 'strong', 'code'):
            return -0.30
        if s in ('a', 'b', 'button', 'title'):
            return 0.10
        return 0.50
    if s.endswith('</'):
        return 0.07
    if s == '>\n':
        return 0.26
    if '(' in s and '\n' in s:
        return 0.21
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (doc, (before + token)[-120:]), value

