"""Mark document ends and tokens that open or introduce structured text.

    The harvested strong activations cluster around delimiters, references, and links,
    so this small token-text rule predicts those recurring boundary signals.
    """

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.lstrip()

    if token == "<|endoftext|>":
        return None, 1.08

    if text.startswith(("${", "^{", "#{")):
        return None, 0.95

    if text.startswith("{"):
        # Compact JSON's opening quote is unlike a space-prefixed object token.
        if text.startswith('{"') and not token[:1].isspace():
            return None, 0.0
        if "\\" in text or "\n" in text or "\r" in text:
            return None, 1.1
        if text.startswith('{"'):
            return None, 0.83
        return None, 0.6

    if text.startswith("]["):
        return None, 0.5

    if text.startswith("["):
        if text.startswith("[$"):
            return None, 0.94
        return None, 1.05 if not token[:1].isspace() else 0.68

    if token == ' "':
        return None, 0.13
    if token.startswith("`\\"):
        return None, 0.16

    if text.startswith(("《", "【")):
        return None, 0.8
    if text.lower().startswith("https"):
        return None, 0.5
    if text == "ISBN":
        return None, 0.28
    return None, 0.0

