    # Latin letters with s-like sounds.
    'ś': (-0.49, -0.20), 'ș': (-0.39, -0.12),
    'ş': (-0.28, 0.02), 'š': (-0.14, 0.10), 'ſ': (-0.16, 0.01),
    # Cyrillic.
    'с': (-0.15, 0.16), 'з': (-0.16, 0.07), 'ш': (-0.12, 0.05),
    # Arabic/Persian.
    'س': (-0.36, -0.24), 'ز': (-0.23, -0.14), 'ش': (-0.22, -0.08),
    # Thai.
    'ส': (-0.49, -0.47), 'ซ': (-0.62, -0.44),
    # Japanese katakana.
    'サ': (-0.46, -0.16), 'シ': (-0.38, -0.15), 'ス': (-0.31, 0.06),
    'セ': (-0.10, 0.0), 'ソ': (-0.47, -0.18),
    # Korean syllables beginning with s.
    '사': (-0.46, -0.38), '스': (-0.32, -0.17),
    '시': (-0.03, 0.07), '세': (-0.13, -0.11), '소': (-0.09, -0.08),
}


def latin_fragment(word, last, initial):
    s = word.lower()
    sib = last in SIBILANTS
    if s == 's':
        if word == 'S':
            return 0.01 if initial else -0.07
        if initial:
            return -0.04
        if sib:
            return 0.03
        if last in VOWELS:
            return -0.16
        return -0.04 if last in SONORANTS else 0.0
    if s == 'z':
        return 0.06 if initial or sib else -0.10
    if len(s) == 2 and s[0] in 'sz' and s[1] in 'aeiouy':
        if initial:
            return 0.07 if s[1] in 'eiy' else 0.0
        if s[0] == 's':
            base = -0.27 if s[1] in 'aouy' else -0.06
        elif s[1] == 'y':
            base = -0.23
        else:
            base = 0.01 if s[1] in 'eiu' else -0.08
    elif s in ('sh', 'st', 'str', 'sk', 'sl', 'sp', 'sm'):
        if initial or sib:
            if s == 'sp':
                return 0.08
            return 0.22 if len(s) == 2 else 0.12
        base = 0.0
        if s == 'sh':
            base = -0.10
        elif s in ('sl', 'sm'):
            base = 0.10
    elif s in ('as', 'is', 'os', 'ys', 'ass', 'iss', 'ish'):
        if initial:
            return 0.05
        base = -0.12 if s[0] in 'iy' else -0.04
        if s == 'iss':
            base = -0.18
    else:
        return 0.002
    if sib:
        return base + 0.16
    if last in SONORANTS:
        return base - 0.04
    return base + (0.0 if last in VOWELS else 0.04)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    end = prev[-1:]
