        if text != word:
            value = -0.62 if greek else -0.24
        elif not greek:
            value = -0.20
        elif last in 'σς':
            value = -0.74
        elif last == 'ω':
            value = -1.07
        else:
            value = -1.28
    elif s == 'ς':
        value = -0.30 if initial else -0.52
        if not initial:
            if last == 'ε':
                value = -0.73
            elif last == 'υ':
                value = -0.62
            elif last in 'αω':
                value = -0.40
    elif s == 'ζ':
        value = 0.10 if initial else -0.72
    elif s in LETTERS:
        if s in KANA_S:
            initial = not prev or not ('ァ' <= end <= 'ヿ' or end == 'ー')
        value = LETTERS[s][int(initial)]
        if s in KANA_S and any(c in prev for c in KANA_S):
            value += 0.22
        if last in SIBILANTS and s in 'сзшſ':
            value += 0.17
        if text != word:
