    'akes': 3.8, 'ikes': 3.35, 'okes': 3.0, 'ukes': 1.9,
    'aker': 1.9, 'aked': 1.9, 'oked': 1.9, 'aking': 1.65,
    'aken': 1.35, 'oker': 1.3, 'oken': 1.2, 'oking': 1.2,
    'iker': 1.1, 'ker': 1.1, 'kers': 1.4, 'ken': .8,
    'kes': 1.85, 'akers': .95, 'iken': .9, 'roke': 2.3,
