    'sake': 4.6, 'wake': 4.0, 'shake': 4.2, 'rake': 3.5, 'jake': 3.1,
    'cake': 3.2, 'fake': 3.4, 'lake': 2.7, 'stake': 3.1, 'flake': 2.7,
    'bake': 2.4, 'snake': 1.0, 'brake': 1.6, 'blake': 1.9,
    'drake': 1.5, 'intake': 1.05,
