    'strike': .65, 'bike': .6, 'like': .05,
    'stroke': 2.0, 'smoke': 2.0, 'woke': 2.25, 'spoke': 1.3,
    'coke': 1.3, 'joke': 1.1, 'broke': .75, 'invoke': 1.3,
    'poke': 3.2, 'choke': 3.6, 'stoke': 2.7,
