        return 0.0
    if word.endswith('ke'):
        return 1.0
    if word.endswith('kes') and word not in {'takes', 'mistakes'}:
        return .65
    if word in {'across', 'among'}:
        return -.2 if spelling[:1].isupper() else -.75
    if word in {'different', 'various', 'separate', 'available'}:
        return -.25
    if word in {'useful', 'valuable', 'beneficial', 'reliable', 'successful',
                'prefer', 'preferred', 'notable'}:
        return -.6
    return 0.0


