"""A signal for blank-line boundaries and veterans-benefit adjudication.

Paragraph/block separators give a negative pulse that fades as the document
reuses separators.  Medical-benefit and legal-claim words give negative
signals, stronger after a veteran/VA mention.  Windows line endings, NUL,
and tool-result markers have separate rules.  State resets per document.
"""
READS = ()

# Terms characteristic of medical-benefit claims and their adjudication.
BENEFIT_LAW = set("claim claims evidence service connection benefits records "
                  "record medical opinion examination duty payment payments "
                  "compensation pension entitled dated incurred".split())
RATINGS = {"rating", "ratings", "rated"}


def word_signal(token, veterans_context):
    word = token.strip()
    lower = word.lower()
    extra = float(veterans_context)
    if lower in {"veteran", "veterans"}:
        return -1.15 - 0.75 * extra
    if lower == "entitlement":
        return -1.5 - 1.1 * extra
    if lower == "itlement":  # The final token of a split 'entitlement'.
        return -3.8
    if lower in {"disability", "disabilities"}:
        return -1.05 - 0.8 * extra
    if lower in RATINGS:
        return -0.7 - 1.1 * extra
    if lower == "appellant":
        return -0.8 - 0.25 * extra
    if word == "Appeals":
        return -1.0 - 2.0 * extra
    if word in {"VA", "BVA", "Vet"} and token.startswith(' '):
        return -0.65 - 0.8 * extra
    if lower in {"board", "appeal", "examiner"}:
        return -0.35 - 0.65 * extra
    if lower in BENEFIT_LAW:
        return -0.30 - 0.85 * extra
    if '§' in word:
        return -0.55 * word.count('§')
    return 0.0


