BREAK_STYLES = {
    "bare": (-0.03, 0.53, 0.30, 0.50),
    "space": (0.15, 0.56, 0.70, 0.50),
    "sentence": (0.10, 0.60, 0.30, 0.20),
    "colon": (0.10, 0.35, 0.30, 0.20),
    "comma": (0.12, 0.46, 1.50, 0.50),
    "code": (0.15, 0.75, 0.05, 0.03),
    "many": (0.15, 0.76, 0.10, 0.03),
    "other": (0.08, 0.60, 0.10, 0.10),
}


def break_signal(token, repeats, other_breaks, veterans_context):
    lines = token.count('\n')
    punctuation = token.rstrip('\r\n')
    if '\r\n' in token:
        if lines >= 2:
            return -0.85 - 0.4 * (min(lines, 3) - 2) - 0.7 * veterans_context
        if punctuation and punctuation.isspace():
            return -0.65 - 0.6 * veterans_context
        return -0.10 - 0.4 * veterans_context
    if lines >= 3:
        style = "many"
    elif not punctuation:
        style = "bare"
    elif punctuation == ' ':
        style = "space"
    elif ';' in punctuation or punctuation.endswith('}'):
        style = "code"
    elif punctuation.endswith(':'):
        style = "colon"
    elif punctuation.endswith(','):
        style = "comma"
    elif punctuation.endswith(('.', '!', '?', '。', '."', ".'")):
        style = "sentence"
    else:
        style = "other"
    level, pulse, same_rate, other_rate = BREAK_STYLES[style]
    familiarity = same_rate * repeats + other_rate * other_breaks
    return level - pulse / (1.0 + familiarity)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        counts, breaks, veterans_context = {}, 0, False
    else:
        _, counts, breaks, veterans_context = carry
    token = prefix.token_strings[-1]
    if token.count('\n') >= 2 or '\r\n' in token:
        n = counts.get(token, 0)
        value = break_signal(token, n, breaks - n, veterans_context)
