        breaks += 1
    else:
        value = word_signal(token, veterans_context)
    if token.strip() in {"veteran", "veterans", "Veteran", "Veterans", "VA", "BVA"}:
        veterans_context = True
    if '\x00' in token:
        value = -0.49
    if token == '</tool_response>':
        value = 0.185
    elif token == '<tool_response>':
        value = 0.13
    return (doc, counts, breaks, veterans_context), value

"""Approximate a detector for s-bearing stems and spelling fragments.

Internal s, ss, and s-consonant clusters are stronger than a bare initial s
or a plural ending. Short fragments continuing a word are stronger than
word-initial fragments. Common grammatical words have separate responses.
Analogous s/sh/z letters in other scripts also raise the prediction.
A few conventional markup and symbol forms have separate responses.
Only the previous character is retained, to recognize word continuation;
this state resets at document boundaries. Most lexical variation is omitted.
"""
READS = ()

WEAK_GRAMMAR = set('is as was has his this its does she so some such '
                   'should shall also because since'.split())
STRONG_GRAMMAR = set('these those most must just us else whose itself '
                     'yourself themselves himself'.split())
TEST_WORDS = set('test tests testing tester tested'.split())

# Sibilant letters/syllables in Latin, Cyrillic, Arabic, Greek, kana and Hangul.
SCRIPT_LETTERS = (
    ('ßſšśşș', 0.94), ('шщ', 0.82), ('с', 0.54), ('з', 0.52),
    ('سش', 0.87), ('σ', 1.00), ('ς', 0.26),
    ('さしすせそサシスセソ', 0.62), ('스시수서사', 0.63),
)


def spelling_response(token, previous):
    text = token.strip()
    w = text.lower()
    word = ''.join(c for c in w if 'a' <= c <= 'z')
    piece = not token.startswith(' ')
    joined = previous.isalpha()

    if w == '<think>':
        return -0.63
    if w == '</think>':
        return -0.21
    if w.startswith('<'):
        return 0.01
    if text == '###':
        return 0.65 if piece else 0.33
    if text == '£':
        return -0.65
    if not piece and text in {':', ':='}:
        return 0.38

    if 's' not in word:
        if w == 'с':
            return 0.20
        for letters, value in SCRIPT_LETTERS:
            if any(c in letters for c in w):
                return value
        if 'z' in word:
            return 0.18
        if any(p in word for p in ('ce', 'ci', 'cy')):
            return 0.16
        return 0.01

    if not piece and w in WEAK_GRAMMAR:
        return -0.03
    if w in STRONG_GRAMMAR:
        return 0.88
    if w in TEST_WORDS:
        return -0.08

    short = len(word) <= 4
    if 's' in word[1:-1]:
        if word.endswith('est'):
            return 0.50
        if short:
            if 'st' in word:
                return 0.93
            if any(p in word for p in ('sh', 'sk', 'sc', 'sp', 'sm')):
                return 1.70 if piece else 1.55
            if 'ss' in word:
                return 1.27
            return 0.81
        if word.startswith('s'):
            return 0.27
        if any(p in word for p in ('sk', 'sc', 'sp')):
            return 1.10
        if 'ss' in word:
            return 0.88
        if word.endswith(('ts', 'ds', 'rs', 'ls', 'ms', 'ns', 'gs', 'ies')):
            return 0.38
        if word.endswith(('ous', 'sible', 'sive', 'sity')):
            return 0.49
        if 'rst' in word:
            return 0.00
        return 0.65

    if word.startswith('s'):
        if not (short and piece):
            return 0.07
        if len(word) == 1:
            return 0.16 if previous and previous.lower() in 'aeiouy' else 0.08
        if word.startswith('st'):
            return 0.48 if joined else 0.05
        if len(word) == 2:
            if joined:
                return 0.37 if previous.lower() == 's' else 1.47
            return 0.45 if word[1] not in 'aeiouy' else 0.00
        return 0.35 if joined else 0.00

    if word.endswith('us') and not word.endswith('ous'):
        return 0.73
    if piece and any(c in text for c in './_-='):
        return 0.45
    if short:
        if piece and len(word) == 2 and word[0] in 'aeioy':
            return 0.33 if joined else 0.18
        return 0.15 if piece else 0.48
    return 0.03


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = spelling_response(token, previous)
    return (document, token[-1:] or previous), float(value)

