    (0.118, CONSTRUCTION),
    (0.042, set('need needs needed necessary'.split())),
    (-0.046, set('use usage try attempt'.split())),
    (-0.053, set('possible either'.split())),
    (-0.074, set('above below'.split())),
    (-0.045, set('north south east west'.split())),
    (0.085, set('therefore consequently accordingly'.split())),
    (0.129, set('obviously apparently literally objectively'.split())),
    (0.080, {'few'}),
)

