        (0.039, set('number amount percentage proportion frequency '
                    'sum rate range'.split())),
        (0.081, set('concept idea definition context purpose direction'.split())),
        (-0.067, set('form type piece bit'.split())),
        (0.056, set('center side position end'.split())),
    ),
    'to': (
        (0.097, set('reference references refer refers referred referring'.split())),
        (-0.070, set('continue continues continued'.split())),
        (-0.037, set('available able ability enough'.split())),
    ),
    'the': (
        (-0.031, {'and', 'or'}),
        (-0.149, {'both', 'either'}),
    ),
    'be': (
        (0.022, set('can must will shall should to'.split())),
        (-0.019, set('may might could would'.split())),
    ),
}


