    word = token.strip()
    lower = word.lower()
    identifier = word.strip('._/(-').lower()
    if ')(' in word:
        return 0.230
    if identifier in {'logger', 'dataset', 'datasets', 'builder', 'builders'}:
        return 0.207
    if word in WEEKDAYS:
        return 0.089
    if lower in WARRANTY:
        return -0.28 if word.isupper() else -0.12
    if token == ' License':
        return -0.138
    if word == '_modules':
        return -0.108
    if word == '/__':
        return -0.180
    if word == '<|im_end|>':
        return 0.035
    if word in {'</tool_call>', '</tool_response>'}:
        return -0.056
    if token == ' may':
        return -0.105
    for score, words in WORD_CLASSES:
        if lower in words:
