PRONOUNS = {
    'I': 3.4, 'you': 4.35, 'he': 3.0, 'she': 2.75,
    'it': 3.8, 'we': 3.6, 'they': 3.45, 'there': 3.6,
    'my': 2.55, 'your': 3.8, 'his': 3.75, 'her': 3.05,
    'its': 3.85, 'our': 2.9, 'their': 3.8,
    'this': 3.7, 'that': 2.4, 'these': 3.4, 'those': 3.8,
}
