    'all': 3.25, 'any': 3.15, 'other': 3.0, 'others': 2.2,
    'one': 2.8, 'each': 2.7, 'every': 2.2, 'another': 2.55,
    'some': 2.3, 'no': 2.0, 'how': 2.7, 'what': 2.3,
    'many': 1.4, 'various': 1.9, 'several': 1.1, 'both': 1.4,
}
ADVERBS = {
    'then': 1.8, 'now': 1.5, 'most': 1.4, 'only': 1.3,
    'not': 1.15, 'more': 0.8, 'thus': 0.8, 'when': 0.7,
    'why': 1.0, 'even': 0.7, 'maybe': 1.5, 'perhaps': 1.3,
    'also': 0.5, 'therefore': 0.8, 'hence': 0.7,
}
NEGATIVE = {
    'with': -1.6, 'without': -1.2, 'from': -0.8,
    'before': -1.3, 'after': -0.7, 'since': -1.0,
    'because': -1.4, 'while': -1.25, 'rather': -1.9,
    'on': -0.5, 'as': -0.5, 'such': -0.6,
    'out': -1.35, 'up': -0.7, 'down': -0.4,
    'back': -0.8, 'around': -1.0, 'through': -0.6,
}

WORDS = ARTICLES | PRONOUNS | DETERMINERS | ADVERBS | NEGATIVE
NUMBER_WORDS = set("two three four five six seven eight nine ten".split())
INDEFINITE_PRONOUNS = set("something anything someone everything".split())
COORDINATION = {
    'and': 1.0, 'or': 0.66, 'but': 0.26, 'nor': 0.43,
    '&': 0.5, '&&': 0.4, '/or': 0.37, '-and': 0.77, '—and': 0.5,
}
OTHER_CUES = {
    'so': 0.10, 'then': 0.12, 'also': 0.07, 'with': 0.05,
    'including': 0.17, 'than': 0.08, 'while': 0.11,
}


def word_response(token, cue):
    word = token.strip()
    if word in WORDS:
        return WORDS[word]
    if word in INDEFINITE_PRONOUNS:
        return 2.5
    if word == 'nothing':
        return 1.85
    if word in NUMBER_WORDS:
        return 1.4
    if token == ' ':
        return 0.55
    if word == '/or':
        return 0.95
    if word in {'The', 'THE'}:
        return 2.4 if word == 'The' else 5.0
    # Capitalized function words are weaker, especially articles A and An.
    if word.istitle() and word.lower() in WORDS:
        lower = word.lower()
        scale = 0.245 if lower in {'a', 'an'} else 0.7
        return scale * WORDS[lower]
    if word.isdigit():
        return -0.5
    if not (word.isascii() and word.isalpha()):
        return 0.0
    # Word fragments and inflectional endings differ from new function words.
    if not token[0].isspace():
        value = -0.5
    elif word[0].isupper():
        value = 0.1
    elif word.endswith(('ed', 's')):
        value = -0.23
    elif word.endswith('ing'):
        value = -0.12
    elif word.endswith('ly'):
        value = 0.2
    else:
        value = -0.04
    return value - {'or': 0.10, 'but': 0.16}.get(cue, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, previous, older_gain = carry
    token = prefix.token_strings[-1]
    cue = previous.strip().lower()
    gain = COORDINATION.get(cue, OTHER_CUES.get(cue, 0.0))
    if previous and previous[0] != ' ' and cue not in {'-and', '—and'}:
        gain *= 0.77 if cue == 'and' else 0.45
    if previous.strip().istitle():
        gain *= 0.74
    # Keep a two-token trace, stronger through linking adverbs.
    trace = gain if cue in {'and', 'or', 'but', 'nor'} else 0.0
    gain += older_gain * (0.23 if cue in {'then', 'also', 'so'} else 0.10)
    value = word_response(token, cue) if gain else 0.0
    if token.strip() in PRONOUNS:
        if cue == 'or':
            gain *= 0.92
        elif cue == 'but':
            gain *= 1.13
    if value < 0 and cue == 'but':
        gain = 0.65
    return (doc, token, trace), float(value * gain)

