    "chance": 0.6, "chances": 0.7, "capacity": 0.2, "potential": 0.4, "tendency": 0.9,
    "propensity": 0.8, "ease": 0.8, "role": 0.6, "presence": 0.6, "way": 0.3, "ways": 0.7,
