"""Approximate the response to a subword join after d.

The main response is at a fragment beginning i or y immediately after a
fragment ending d. It folds case and accents and groups corresponding
letters and front-vowel marks in several scripts. Responses weaken with length;
the second letter modulates it. Other vowel starts are weaker or negative.
Documentation-comment openers are a separate small negative feature.
"""
import math
import unicodedata

READS = ()

# Letter/sound groups for this rule, not a table of words or token identities.
LETTERS = str.maketrans({
    'д': 'd', 'δ': 'd', 'د': 'd', 'द': 'd', 'ด': 'd',
    'и': 'i', 'і': 'i', 'ι': 'i', 'ı': 'i', 'ی': 'i', 'ي': 'i',
    'ि': 'i', 'ी': 'i', 'ิ': 'i', 'ี': 'i',
    'а': 'a', 'о': 'o', 'е': 'e', 'э': 'e', 'у': 'u',
    'ю': 'y', 'я': 'y', 'ы': 'y', 'ь': 'y', 'ъ': 'y',
    'н': 'n', 'м': 'm', 'в': 'v', 'б': 'b', 'п': 'p',
    'р': 'r', 'л': 'l', 'т': 't', 'с': 's', 'к': 'k',
    'г': 'g', 'ф': 'f',
})


def letters(text):
    text = unicodedata.normalize('NFKD', text.lower()).translate(LETTERS)
    return ''.join(c for c in text if not unicodedata.combining(c))


def joined_response(fragment, previous):
    first, second = fragment[0], fragment[1:2]
    current_length = len(fragment) - 1
    previous_length = len(previous.strip()) - 1
    if first == 'i':
        strength = 3.4
        if second and second in 'bmpv':  # Labial consonants.
            strength += 1.75
        elif second == 'l':
            strength += 1.45
        elif second in ('n', 'd'):
            strength -= 0.6 if second == 'n' else 1.45
        elif second and second not in 'aeiouyr':
            strength += 0.9
        value = strength * math.exp(
            -0.18 * current_length - 0.14 * previous_length
        ) - 0.52
        return max(0.0, value)
    if first == 'e':
        strength = 1.75
        if second in ('n', 'd'):
            strength -= 0.4 if second == 'n' else 1.0
        elif second and second in 'bmpvstfh':
            strength += 0.5
        elif second:
            strength += 0.2
        return strength * math.exp(
            -0.28 * (current_length + previous_length)
        )
    if first == 'y':
        return max(0.0, 2.5 * math.exp(
            -0.12 * current_length - 0.10 * previous_length
        ) - 0.6)
    if first in 'ao':
        strength = -0.55 if first == 'a' else -0.3
        if not current_length:
            strength *= 0.3
        return strength * math.exp(-0.2 * previous_length)
    strength = {
        'u': 0.6, 'j': 0.9, 'n': -0.55, 'b': -0.8,
        'f': -0.5, 'g': -0.2, 'r': -0.1,
    }.get(first, 0.0)
    return strength * math.exp(
        -0.25 * current_length - 0.2 * previous_length
    )


