    elif word in {"сум", "сумма"}:
        value = -1.2
    else:
        value = 0.0

    return None, float(value)

programs.sol:
"""Detect the spelling chunk av, including Cyrillic ав and яв.

Short, isolated chunks give a large negative response. Extra letters, a
preceding vowel, and token-boundary punctuation usually weaken it; some short
endings preserve it. Frequent grammatical words are weak exceptions. This is
an orthographic detector, not a detector of a topic or of complete words.
Tool-call delimiters have their own smaller negative responses.
"""
READS = ()

# Grammatical uses of the same spelling are unlike short subword fragments.
POSSESSION_FORMS = {'have', 'having', 'haven', 'haves', 'gave'}
ROMANCE_HAVE_FORMS = {'avoir', 'avez', 'avait', 'avaient',
                      'avons', 'aveva', 'avevano'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    if token == '<tool_call>':
        return None, -0.86
    if token == '</tool_call>':
        return None, -0.17
    plain = lower.strip("'-_/.()\"")
    if plain in POSSESSION_FORMS:
        return None, -0.05 if plain in {'have', 'gave'} else -0.17
    if plain in ROMANCE_HAVE_FORMS:
        return None, -0.45
    if plain == 'avec':  # French grammatical 'with'.
        return None, 0.0
    if plain.startswith(('leav', 'behav', 'javascript')):
        return None, -0.08
    if plain.startswith(('avail', 'avenue')):
        return None, -0.15

    hits = [(lower.find(s), s) for s in ('av', 'ав', 'яв') if s in lower]
    if not hits:
        return None, 0.0
    index, motif = min(hits)
    before, after = lower[:index], lower[index + 2:]
    letters = ''.join(c for c in before if c.isalpha())
    trailing = len(after)
    # Short fragments are strongest; letters around the motif attenuate it.
    strength = (4.4, 2.1, 1.3, 1.0)[min(trailing, 3)]
    strength *= 0.82 ** min(len(letters), 5)
    strength *= 0.69 ** sum(c in 'aeiouаеёиоуыэюя' for c in letters)
    if token[:1].isspace():
        strength *= 0.78
    if any(not c.isalpha() for c in before):
        strength *= 0.54
    if before in ("'", '’'):
        strength *= 1.62
    if motif != 'av':
        strength *= 0.64
    if motif == 'яв':
        strength *= 0.61
    if after.startswith('i'):
        strength *= 1.39
    if after.startswith(('en', 'er')):
        strength *= 2.20
    if letters == 'n':  # nav fragments.
        strength *= 1.49
    return None, -float(min(strength, 4.7))

"""Negative response to -ual words and suffix fragments.

Actual/manual/annual are strongest. Their adverbs and plurals are attenuated.
Other -ual endings, -uel fragments, and periodic-frequency words are weaker.
Only the current token's spelling is used; everything else predicts zero.
"""
READS = ()

STRONG_WORDS = {
    'manual': -4.9, 'actual': -4.3, 'annual': -3.8,
    'sexual': -2.6, 'dual': -2.5, 'visual': -1.7,
    'mutual': -1.7, 'textual': -2.1, 'atual': -2.1,
    'continual': -1.8, 'individual': -0.8,
}
MEDIUM_WORDS = {'casual', 'gradual', 'habitual', 'perpetual', 'eventual'}
WEAK_WORDS = {'usual', 'virtual', 'equal', 'factual'}
PERIODIC = {'daily', 'weekly', 'monthly', 'quarterly', 'yearly', 'hourly'}
SUFFIXES = {
    'ual': -3.65, 'ually': -2.1, 'uality': -2.0,
    'uale': -1.65, 'uales': -1.8, 'uali': -1.1,
    'uel': -0.8, 'uelle': -0.8,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lstrip('._/-').lower()
    if word in SUFFIXES:
        return None, SUFFIXES[word]
    if word in PERIODIC:
        return None, -1.4 if word in {'daily', 'monthly', 'quarterly'} else -1.0
    stem, factor = word, 1.0
    if word.endswith('ually'):
        stem, factor = word[:-2], 0.55
        if stem in {'actual', 'gradual'}:
            factor = 0.2
        elif stem == 'manual':
            factor = 0.65
        elif stem in {'sexual', 'mutual'}:
            factor = 0.4
        elif stem in {'individual', 'visual'}:
            factor = 0.85
    elif word.endswith('uals'):
        stem, factor = word[:-1], 0.8
        if stem == 'individual':
            factor = 0.4
    if stem.endswith('ual'):
        default = -1.1 if stem in MEDIUM_WORDS else -0.6
        value = STRONG_WORDS.get(stem, default)
        if stem in WEAK_WORDS:
            value = -0.2 if stem == 'usual' else 0.0
        return None, float(value * factor)
    return None, 0.0

programs.haiku:
"""Component layers.0.mlp.down_proj:2871: a negative detector for "actual"-type words.

It reads the current word-piece and writes a negative value when that piece belongs to one
of a few word families, with three strengths:
  * strongest (about -4): "actual", "annual", "manual" and their capitalised and plural forms,
    and the bare fragment "ual" that splits such words;
  * medium (about -2): other -ual words such as sexual, dual, visual, mutual, and the
    -ually/-uality endings and the time word "annually";
  * recurring-time words (about -1.3): daily, weekly, monthly, yearly, and Chinese 实际
    (actual) and 每天/每年/每月 (every day/year/month);
  * weak (about -0.8): actually, individual, residual, casual, binary, automatic, and the
    plural people nouns adults, males, females, humans.
Every other token predicts 0. The positions it fires on are the token that completes or
is one of these words.
"""

READS = ()

STRONG = {"actual", "annual", "manual", "manuals", "ual", "actuals", "manually"}
MID = {"sexual", "dual", "visual", "mutual", "textual", "perpetual", "ually", "uality", "atual",
       "uale", "annually", "sexually", "mutually", "uali"}
TIME = {"daily", "weekly", "monthly", "yearly", "quarterly", "nightly", "seasonal"}
WEAK = {"actually", "individual", "individually", "intellectual", "residual", "casual", "binary",
        "automatic", "automated", "adults", "adult", "males", "females", "humans"}
CHINESE = {"实际": -2.0, "實際": -2.0, "每天": -0.5, "每年": -1.0, "每月": -0.7, "日常": -1.6}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    word = tok.lower()
    if tok in CHINESE:
        return carry, CHINESE[tok]
    if word in STRONG:
        return carry, -4.0
    if word in MID:
        return carry, -2.0
    if word in TIME:
        return carry, -1.3
    if word in WEAK:
        return carry, -0.8
    return carry, 0.0

programs.luna:
"""Use line-break and punctuation cues for a sparse boundary response.

Single breaks score positively; periods and repeated breaks lower that score.
A standalone closing angle bracket is positive, while end-of-text is negative.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "<|endoftext|>":
        return None, -0.5
    if "\n" in token or "\r" in token:
        first = min((i for i in (token.find("\n"), token.find("\r"))
                     if i >= 0), default=len(token))
        if token[:first].rstrip().endswith("."):
            return None, 0.4
        breaks = token.count("\n") + token.count("\r")
        return None, 0.8 if breaks == 1 else 0.5
    if token.strip() == ">":
        return None, 0.55
    return None, 0.0

programs.sol:
"""Approximate a tokenization-sensitive word/identifier-start letter signal.

An unspaced single letter after whitespace or punctuation has a negative
response, stronger for lowercase than uppercase and after opening brackets or
quotes. Inside words and after escape markers it is mostly quiet. Two-letter
prefixes respond more weakly, especially capitals. Null bytes are ignored when
locating word boundaries; combining marks remain part of their preceding word.
Decoded prefixes repair split Unicode characters, including historical long s.
Fine token-specific and longer-context variation is deliberately not modeled.
"""
import unicodedata

READS = ()
OPENING = set('([（［"\'“‘„«')
CLOSING = set(')]}）］｝')
MODIFIERS = set('%^∂×')
VOWELS = set('aeiou')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    last = previous[-1:]
    if last == '\ufffd' and prefix.position > 0:
        # A token decoded alone can hide the end of a multibyte letter.
        last = prefix.text_prefixes[-2][-1:]
    if token == '\ufffd':
        decoded = prefix.text_prefixes[-1][-1:]
        if decoded == 'ſ':
            token = decoded
            if prefix.position > 0:
                last = prefix.text_prefixes[-2].rstrip('\ufffd')[-1:]
    escaped_break = previous.endswith(('\\n', '\\r', '\\t'))
    mark = bool(last) and unicodedata.category(last).startswith('M')
    boundary = bool(last) and not mark and (not last.isalnum() or escaped_break)
    boundary = boundary and last != '\\'
    value = -0.002
    if len(token) == 1 and token.isalpha():
        name = unicodedata.name(token, '')
        latin = token.isascii()
        if latin:
            if not previous:
                value = 0.04
            elif boundary:
                strength = 1.05 if token.islower() else 0.69
                if last.isspace():
                    strength = 1.15 if token.islower() else 0.74
                elif last in OPENING:
                    strength = 1.27 if token.islower() else 0.88
                elif last in CLOSING or last in MODIFIERS:
                    strength = 0.65 if token.islower() else 0.46
                elif last == '\ufffd':
                    strength = 0.55 if token.islower() else 0.45
                if escaped_break:
                    strength = 0.73 if token.islower() else 0.49
                elif last == "'" and previous.endswith("\\'"):
                    strength = 0.42 if token.islower() else 0.6
                value = -strength
            elif last.isdigit() and token.islower():
                value = -0.16
            elif last.isalpha() and not last.isascii():
                value = -0.15 if token.islower() else -0.34
            else:
                value = 0.0 if token.islower() else 0.04
        elif boundary:
            if 'CYRILLIC' in name:
                value = -1.1 if token.islower() else -0.49
                if last in OPENING:
                    value = -1.35 if token.islower() else -0.61
                elif last == '\ufffd':
                    value = -0.15
            elif 'LATIN' in name:
                value = -0.6 if token.islower() else -0.4
            elif 'GREEK' in name:
                value = -0.5 if last.isspace() or last in OPENING else -0.2
            elif 'ARABIC' in name:
                value = (-0.8 if last.isspace() else
                         -1.1 if last in OPENING else -0.6)
    elif token.isascii() and token.isalpha() and boundary:
        if len(token) == 2:
            if token.islower():
                vowels = sum(c in VOWELS for c in token)
                value = (-0.38 if vowels == 1 else
                         -0.26 if vowels == 2 else -0.21)
            else:
                value = -0.09
        elif len(token) == 3:
            value = -0.04
        else:
            value = 0.03
    visible = prefix.token_strings[-1].rstrip('\x00')
    return (doc, visible if visible else previous), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:2874: a "we can / we must" detector.

What it does, in plain terms: it is quiet on most tokens, and it wakes up on the
word that follows a first-person plural subject "we" when that word is a modal or
an ability/knowledge verb, and on "we" itself after "if" or "when".

Rules, with the rough activation each gives (the real values vary):
- the word right after "we":
    "can"                          +3.8   (the strongest case, "We can ...")
    must, may, might, need, should,
    will, could, cannot, 'll         +1.8
    know, learn, see, note, begin,
    now, already, all               +1.5
    show, provide, offer, suggest,
    recommend, found, present, ...  -1.5  (presenting/offering verbs, "We show ...")
- "can" after another subject (you, I, they, it, which...)  +1.0 (after "how": +0.3)
- "we" right after "if" +1.9, after "when" +0.8
- "us" after "let" +1.3; "'s" after "let" (let's) +0.8
- "you" as the object of help/give/show/thank/tell/ask   -1.0 (for example "help you")
- everything else 0

The program is stateless: it only reads the last token or two of the prefix.
Only the ordering of these rules is a judgement; no table of token ids is used.
"""

READS = ()

MODALS = {"must", "may", "might", "need", "should", "will", "could", "cannot", "'ll", "’ll"}
KNOW = {"know", "learn", "see", "note", "begin", "now", "already", "all"}
PRESENT = {
    "show", "showed", "suggest", "recommend", "provide", "found", "present", "offer",
    "give", "describe", "demonstrate", "prove", "serve", "observe", "observed",
    "calculate", "thank", "ask",
}
OBJECT_YOU_VERBS = {"help", "give", "gives", "provide", "show", "thank", "ask", "tell", "allow"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if prev == "we":
        if cur == "can":
            return None, 3.8
        if cur in MODALS:
            return None, 1.8
        if cur in KNOW:
            return None, 1.5
        if cur in PRESENT:
            return None, -1.5
        return None, 0.0
    if cur == "can":
        return None, 0.3 if prev == "how" else 1.0
    if cur == "we":
        return None, {"if": 1.9, "when": 0.8}.get(prev, 0.0)
    if cur == "us" and prev == "let":
        return None, 1.3
    if cur in ("'s", "’s") and prev == "let":
        return None, 0.8
    if cur == "you" and prev in OBJECT_YOU_VERBS:
        return None, -1.0
    return None, 0.0

