        return None, 2.8
    return None, 0.0

programs.sol:
"""A lexical response to prompts, triggers, and weaker cues to action.

Strong negative pulses mark forms of 'prompt' and 'trigger'. Smaller pulses
mark reminders, alerts, encouragement, signals, stimulation, and causation.
Some Chinese action cues are included. Split endings are recognized from a
short text tail. An immediately following article or preposition can echo a
cue. GPT and impromptu spellings are also included. Most tokens produce
zero; this is a spelling-based approximation, not semantic causal analysis.
"""
from string import whitespace, punctuation

READS = ()
PROMPTS = {'prompt': -6.2, 'prompts': -5.25, 'prompting': -5.2,
           'prompted': -4.5, 'promptly': -2.0}
TRIGGERS = {'trigger': -3.6, 'triggers': -3.7,
            'triggering': -3.3, 'triggered': -2.6}
REMINDING = ('alert', 'remind')
ENCOURAGING = ('encourag', 'foster', 'motivat', 'inspir', 'empower', 'thrive')
STIMULATING = ('pulse', 'stimul', 'spurr', 'provok')
CHINESE_PROMPTS = {'提示', '提醒'}
CHINESE_ACTION_CUES = {'刺激', '促进', '促', '激发', '引发', '引发了',
                       '鼓励', '启发', '启示', '引导', '及时', '警', '醒',
                       '唤醒', '警惕', '警示', '督促'}
ECHO = {'the': .35, 'of': .35, 'a': .22, 'to': .12, 'for': .25}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, tail, previous_cue = carry
    token = prefix.token_strings[-1]
    word = token.strip(whitespace + punctuation).lower()
    value = 0.0
    if word in PROMPTS:
        value = PROMPTS[word]
    elif word in TRIGGERS:
        value = TRIGGERS[word]
    elif word == 'rompt':
        value = -4.5
    elif word.startswith(REMINDING) or word in {'urgent', 'urgency'}:
        value = -0.95
    elif word.startswith(ENCOURAGING + STIMULATING) or word in {
            'urge', 'urges', 'urged', 'urging', 'signal', 'signals',
            'spark', 'sparks', 'sparked', 'sparking', 'cue', 'cues'}:
        value = -0.72
    elif word.startswith('incentiv') or word in {'warrant', 'warrants'}:
        value = -1.15
    elif word in {'cause', 'causes', 'caused', 'causing'}:
        value = -0.33
    elif word in {'stem', 'stems', 'timely'}:
        value = -0.75
    elif word in {'cmd', 'warning'}:
        value = -0.5
    elif word in CHINESE_PROMPTS:
        value = -1.95
    elif word in {'预警', '促使'}:
        value = -1.6
    elif word == '触发':
        value = -2.3
    elif word in CHINESE_ACTION_CUES:
        value = -0.75

    joined = (tail + token).lower()
    # Endings completing a cue word when it is split over multiple tokens.
    if word == 'pts' and joined.endswith('prompts'):
        value = -5.2
    elif word == 'pt' and joined.endswith('prompt'):
        value = -4.6
    elif word in {'igger', 'iggers'} and joined.endswith(('trigger', 'triggers')):
        value = -3.1 if word == 'iggers' or token.isupper() else -0.85
    elif word == 'ly' and joined.endswith('promptly'):
        value = -2.8
    elif word in {'ed', 'ing', 's', 'ers', 'ates'} and previous_cue < -0.3:
        if joined.endswith(('triggered', 'triggering')):
            value = -3.2
        elif joined.endswith(('prompted', 'prompting', 'prompts')):
            value = -4.0
        else:
            value = min(value, -0.7)
    elif word == 'u' and joined.endswith('impromptu'):
        value = -1.2
    elif word == 'pt' and joined.endswith('gpt'):
        value = -0.75
    cue = value
    if word in ECHO and previous_cue < -0.3:
        value += previous_cue * ECHO[word]
    return (doc, joined[-24:], cue), float(value)

"""A lexical paragraph-boundary detector, with Markdown context.

The base response to three or five line feeds is positive; four is usually
negative. Four line feeds attached to a sentence-ending period are especially
negative,
but repeated four-line separators in one document are weaker. Closing
code fences and level-three headings make a following break more negative.
Chat-message, reasoning, and tool-call markers have separate responses;
chat starts and the following role labels are stronger at document start.
The rare high-importance examples were blank-line separators. This models
that formatting response, but leaves most word-specific activity unexplained.
Ordinary text receives a small near-zero background value.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False, 0)
    _, line, previous, repeated, position = carry
    token = prefix.token_strings[-1]
    n = token.count('\n') if '\r' not in token else 0
    punctuation = token.rstrip('\n')
    value = -0.00054
    if n == 2:
        value += 0.0041
        if '.' in punctuation:
            value -= 0.0175
            if ')' in punctuation:
                value -= 0.0237
        if '?' in punctuation:
            value += 0.0422
        if ',' in punctuation:
            value += 0.0142
    elif n == 3:
        value += 0.147
        if punctuation:
            value -= 0.057
        if '}' in punctuation or '{' in punctuation:
            value -= 0.024
        if ';' in punctuation:
            value -= 0.050
        if punctuation.isspace():
            value -= 0.039
    elif n == 4:
        value -= 0.081
        if '.' in punctuation:
            value -= 0.504
            if repeated:
                value += 0.368
        else:
            if any(c in punctuation for c in ')}];'):
                value -= 0.104
            if repeated:
                value += 0.065
        if '?' in punctuation:
            value += 0.15
    elif n == 5:
        value += 0.133 if not punctuation else 0.039
    elif n > 5:
        value += 0.034
    if 2 <= n <= 4:
        if line.lstrip().startswith('### '):
            value -= {2: 0.088, 3: 0.341, 4: 0.139}[n]
        if previous == '```':
            value -= {2: 0.121, 3: 0.200, 4: 0.528}[n]
        if previous == '---':
            value -= {2: 0.0, 3: 0.147, 4: 0.165}[n]
    if token == '<|im_start|>':
        value = 0.202 if position == 0 else -0.015
    elif previous == '<|im_start|>' and token in ('user', 'assistant', 'system'):
        if position == 1:
            value = {'user': 0.196, 'assistant': 0.177, 'system': 0.296}[token]
        else:
            value = -0.017 if token == 'assistant' else -0.009
    elif token == '<think>':
        value = 0.156
    elif token == '</think>':
        value = -0.058
    elif token == '<tool_call>':
        value = -0.015
    elif token == '</tool_call>':
        value = -0.130
    elif token == '<|im_end|>':
        value = -0.023
    repeated = repeated or n == 4
    # Retain the start of the current line to recognize Markdown headings.
    if '\n' in token:
        line = token.rsplit('\n', 1)[-1][:64]
    else:
        line = (line + token)[:64]
    return (doc, line, token, repeated, position + 1), float(value)

