    "сестра", "муж", "жена", "父母", "父親", "母親",
    "父亲", "母亲",
    "兄弟", "姐妹",
    "家族", "家庭", "家人", "丈夫", "妻子", "兒子", "女兒", "亲属",
    "父", "母", "兄", "妹", "弟", "姉", "夫", "妻", "息子",
}

FAMILY_WORDS = {
