    elif word in PUBLIC_BELONGING:
        value = 0.75
    elif word in PROPERTY:
        value = 0.22
    else:
        value = 0.0
    return None, value

programs.sol:
"""A sparse local-phrase approximation, especially 'that/those of'.

Distal demonstratives followed by a preposition or relative clause give a
positive signal; comparisons boost 'of'. 'Outside of' and words following
'during' have the opposite sign. Most other tokens get zero. Only the last
two tokens within the current document are retained. A few document-initial
prepositions and source-code import directives have separate predictions.
This captures selected strong responses, not the small background variation.
"""
READS = ()

PREPOSITIONS = set('in with on for to at by from about between under'.split())
REFERENCE_NOUNS = set('time times day days year years case cases part parts'.split())
RELATIONAL_NOUNS = set('end front range form variety type types area piece level '
                      'view volume surface version year field department list '
                      'beginning lack'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = ()
    else:
        history = carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().casefold()
    previous = history[-1] if history else ''
    prev = previous.casefold()
    before = history[-2].casefold() if len(history) > 1 else ''
    value = 0.0
    if raw[:1].isspace():
        if prev in {'that', 'those'}:
            plural = prev == 'those'
            if word == 'of':
                value = 2.40 if plural else 2.18
                if before == 'than':
                    value += 0.38
                elif before in {'is', 'was', 'like', 'of'}:
                    value -= 0.18
            elif word in {'in', 'with'}:
                value = 1.00 if plural else 0.53
            elif word in PREPOSITIONS:
                value = 0.59 if plural else 0.34
            elif word in {'who', 'which', 'whose', 'that'}:
                value = 0.53 if plural else 0.40
            elif word in REFERENCE_NOUNS:
                value = 0.35 if plural else 0.38
            elif word == 'the':
                value = 0.08
            elif plural and word.endswith(('ing', 'ed')):
                value = 0.35
            elif not plural and word in {'are', 'were'}:
                value = -0.14
            elif not plural and word in {'many', 'such'}:
                value = 0.24
        elif word == 'of':
            if prev in {'as', 'which', 'whether', 'but', 'especially'}:
                value = 0.64
            elif prev == 'because':
                value = 0.33
            elif prev in {'each', 'either', 'best'}:
                value = 0.29
            elif prev in {'some', 'any', 'many', 'couple', 'and'}:
                value = 0.15
            elif prev == 'outside':
                value = -0.68
            elif prev == 'inside':
                value = -0.41
            elif prev == 'out' or prev in RELATIONAL_NOUNS:
                value = -0.17
            elif before in {'that', 'those'}:
                value = 0.29
        elif word in PREPOSITIONS and prev in {'this', 'these'}:
            value = 0.23
        elif word in PREPOSITIONS and prev in {'as', 'but', 'than', 'especially'}:
            value = 0.26
        if prev == 'during':
            if word in {'this', 'these'}:
                value = -0.98 if previous == 'During' else -0.69
            elif word in {'the', 'a', 'an', 'his', 'her', 'their'}:
                value = -0.32 if previous == 'During' else -0.18
            elif word.isalpha():
                value = -0.15
        if prev == 'regarding' and word == 'this':
            value = -0.70 if previous == 'Regarding' else -0.20
        if word == 'to' and prev == 'how':
            value = 0.19
        if word == 'the' and prev == 'than':
            value = 0.25
        if word in {'qui', 'de', 'des'} and prev in {'ceux', 'celui', 'celle', 'celles'}:
            value = 0.37
    elif prev == 'that' and word in {"'s", '’s'}:
        value = 0.21
    elif prev == '那' and word in {'裡', '里', '裏', '麽', '么'}:
        value = 0.70
    # Code-import directives and leading prepositions are distinct at a reset.
    if not history:
        if word == '#include':
            value = -0.84
        elif word == 'using':
            value = -0.89 if raw == 'using' else -0.53
        elif word in {'during', 'including', 'regarding', 'concerning'}:
            value = -0.70
        elif word in {'on', 'between', 'about'}:
            value = -0.43
        elif word in {'in', 'from'}:
            value = -0.23
        elif raw in {' to', ' and', ' or'}:
            value = 0.23
    elif raw == '#include':
        value = -0.11
    elif raw == 'import':
        value = 0.13
    elif raw == ' import':
        value = -0.07
    return (doc, (history + (raw.strip(),))[-2:]), float(value)

programs.haiku:
"""Demonstrative-pronoun + preposition detector (layers.0.mlp.down_proj:2879).

The component reads the MLP hidden state and writes a small signal into the residual
stream. It is large in one construction: a demonstrative pronoun ("that", "those") used on
its own as the head of a phrase, immediately followed by a preposition or relative word.
"that of X", "those of X" ("similar to those of", "than that of") give about +2.4;
"those with", "Those with" about +1; "those who", "that in", "that which" about +0.5;
other prepositions after "that"/"those" (on, to, for, by) about +0.4. "that is", "that the"
and similar stay near 0.
Smaller signals: "which of" / "As of" (about +0.7) and "because of" (about +0.3); "During this"
is negative (about -1). Everything else is 0.
"""
READS = ()

DEMONSTRATIVES = {"that", "those", "Those"}
AFTER_DEMONSTRATIVE = {"of": 2.4, "with": 0.9, "who": 0.55, "in": 0.5, "which": 0.5,
                       "on": 0.4, "to": 0.4, "for": 0.4, "by": 0.4}
BEFORE_OF = {"which": 0.7, "Which": 0.7, "As": 0.7, "as": 0.7, "because": 0.3}
NEGATIVE_AFTER_DURING = {"this": -1.0, "the": -0.35}


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    prev = prefix.token_strings[-2].strip()
    cur = prefix.token_strings[-1].strip()
    if prev in DEMONSTRATIVES and cur in AFTER_DEMONSTRATIVE:
        return None, AFTER_DEMONSTRATIVE[cur]
    if cur == "of" and prev in BEFORE_OF:
        return None, BEFORE_OF[prev]
    if prev in ("During", "during") and cur in NEGATIVE_AFTER_DURING:
        return None, NEGATIVE_AFTER_DURING[cur]
    return None, 0.0

programs.luna:
"""Mark a few short patterns in which a demonstrative gets a qualifier.

The component also shows small pulses on two temporal phrases and on several
unusual single-token starts.  Unmatched words receive zero.
"""
READS = ()


def step(carry, prefix, upstream):
    i = prefix.position
    docs = prefix.document_ids
    boundary = i > 0 and docs[i] != docs[i - 1]
    previous = ""
    if i > 0 and not boundary:
        previous = prefix.token_strings[i - 1].strip().lower()
    word = prefix.token_strings[i].strip().lower()

    if word == "of":
        if previous == "that":
            return None, 2.1
        if previous in {"as", "whether", "particle"}:
            return None, 0.65
        if previous == "outside":
            return None, -0.65
    if word == "case" and previous == "that":
        return None, 0.5
    if previous == "those":
        if word == "who":
            return None, 0.58
        if word in {"which", "that"}:
            return None, 0.5 if word == "which" else 0.38
        if word == "interested":
            return None, 0.47
    if word == "which" and previous == "that":
        return None, 0.48
    if word == "qui" and previous in {"ceux", "celui"}:
        return None, 0.34
    if word == "in" and previous == "that":
        return None, 0.5
    if word == "with" and previous == "that":
        return None, 0.6
    if word in {"late", "rush"} and previous == "during":
        return None, -0.5
    if word == "this" and previous == "regarding":
        return None, -0.65
    if word == "look" and previous == "on":
        return None, -0.55
    if word == "裡" and previous == "那":
        return None, 0.65
    if i == 0 and word in {"concerning", "on", "including"}:
        return None, -0.52
    if boundary and word == "#include":
        return None, -0.83
    return None, 0.0
